// NAP-104: the browser reader of .napx packages and leases (lib/napx.ts) against bytes made by the server code
// (scripts/fixtures/napx-v1.json, regenerated by backend/scripts/make_napx_fixture.py). Node ≥ 22.18 strips types.
import assert from "node:assert/strict";
import { createHash, webcrypto } from "node:crypto";
import { readFileSync } from "node:fs";
import test from "node:test";
import * as napx from "../lib/napx.ts";

const fx = JSON.parse(readFileSync(new URL("./fixtures/napx-v1.json", import.meta.url), "utf8"));
const pkgBytes = Buffer.from(fx.package, "base64");
const device = () => webcrypto.subtle.importKey("pkcs8", Buffer.from(fx.device_pkcs8, "base64"),
  { name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"]);

async function play(bytes, key) {
  const blob = new Blob([bytes]);
  const h = await napx.readHeader(blob);
  await napx.verifyManifest(h, fx.signing_key);
  const { payload } = await napx.readLease(fx.lease, fx.signing_key);
  assert.equal(await napx.manifestSha256(h), payload.manifest_sha256);
  const cek = await napx.openSealed(key ?? await device(), payload.key, payload.lid);
  const parts = [];
  for await (const seg of napx.decryptSegments(blob, h, cek)) parts.push(seg);
  return Buffer.concat(parts);
}

const code = async (p) => { try { await p; } catch (e) { return e.code ?? String(e); } return "ok"; };

test("server package + lease decrypt in WebCrypto to the original bytes", async () => {
  const out = await play(pkgBytes);
  assert.equal(createHash("sha256").update(out).digest("hex"), fx.plaintext_sha256);
  const { verified, payload } = await napx.readLease(fx.lease, fx.signing_key);
  assert.ok(verified, "Ed25519 is available in Node: the signature must be checked");
  assert.equal(payload.layout, "headphones");
});

test("any change to the package is detected", async () => {
  const h = await napx.readHeader(new Blob([pkgBytes]));
  const seg = fx.segment_size + 16;
  const flipped = Buffer.from(pkgBytes); flipped[h.dataOffset + 5000] ^= 1;
  const swapped = Buffer.concat([pkgBytes.subarray(0, h.dataOffset), pkgBytes.subarray(h.dataOffset + seg, h.dataOffset + 2 * seg),
    pkgBytes.subarray(h.dataOffset, h.dataOffset + seg), pkgBytes.subarray(h.dataOffset + 2 * seg)]);
  assert.equal(await code(play(flipped)), "tampered");
  assert.equal(await code(play(swapped)), "tampered");
  assert.equal(await code(play(pkgBytes.subarray(0, pkgBytes.length - 1))), "truncated");
  assert.equal(await code(play(Buffer.concat([pkgBytes, Buffer.from("x")]))), "trailing_data");
  const edited = Buffer.from(pkgBytes.toString("latin1").replace('"size":10000', '"size":10001'), "latin1");
  assert.equal(await code(play(edited)), "bad_signature");
  assert.equal(await code(napx.readHeader(new Blob([Buffer.from("fLaC....")]))), "not_napx");
});

test("lease: another device, an edited lease and an expired lease do not open", async () => {
  const other = (await webcrypto.subtle.generateKey({ name: "ECDH", namedCurve: "P-256" }, false, ["deriveBits"])).privateKey;
  assert.equal(await code(play(pkgBytes, other)), "wrong_device");
  const [h, p, s] = fx.lease.split(".");
  const payload = JSON.parse(Buffer.from(p, "base64url").toString());
  const forged = [h, Buffer.from(JSON.stringify({ ...payload, exp: payload.exp + 1 })).toString("base64url"), s].join(".");
  assert.equal(await code(napx.readLease(forged, fx.signing_key)), "bad_lease");
  assert.equal(await code(napx.readLease(fx.lease, fx.signing_key, payload.exp)), "lease_expired");
});

test("device key: private half cannot be exported, public half is SPKI", async () => {
  const { pair, spki } = await napx.newDeviceKey();
  assert.equal(pair.privateKey.extractable, false);
  assert.equal(Buffer.from(spki, "base64")[0], 0x30);
  await assert.rejects(webcrypto.subtle.exportKey("pkcs8", pair.privateKey));
});
